import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Rekening r = new Rekening();
        Thread a = new Thread(() -> r.setor(100));
        Thread b = new Thread(() -> r.setor(100));
        a.start();
        b.start();
        a.join();
        b.join();
        System.out.println("Saldo akhir: " + r.saldo());
    }
}

class Rekening {
    private int saldo;

    void setor(int jumlah) {
        int lama = saldo;
        Jeda.ms(100);              // meniru pekerjaan lain, misalnya mencatat ke database
        saldo = lama + jumlah;
    }

    int saldo() {
        return saldo;
    }
}

class Jeda {
    static void ms(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

