        }
        for (Thread t : pembeli) {
            t.join();
        }
        for (int i = 0; i < kursi.size(); i++) {
            System.out.println("Pembeli " + (i + 1) + " kursi " + kursi.get(i) + ": " + (hasil[i] ? "dapat" : "sudah terjual"));
        }
    }
}

